// Initialize shopping cart object
let cart = {};
// Add item to shopping cart
function addToCart(productId) {
	if (cart[productId]) {
		cart[productId].quantity++;
	} else {
		cart[productId] = {
			name: '',
			price: 0,
			quantity: 1
		};
	}
	// Update cart display
	updateCartDisplay();
}
// Remove item from shopping cart
function removeFromCart(productId) {
	delete cart[productId];
	// Update cart display
	updateCartDisplay();
}
// Update shopping cart display
function updateCartDisplay() {
	const cartItems = document.getElementById('cart-items');
	const cartTotal = document.getElementById('cart-total');
	// Clear cart display
	cartItems.innerHTML = '';
	// Populate cart display with items
	let total = 0;
	for (const productId in cart) {
		const product = getProductById(productId);
		const cartItemDiv = document.createElement('div');
		cartItemDiv.className = 'cart-item';
		cartItemDiv.innerHTML = `
			<img src="${product.image}" alt="${product.name}">
			<p>${product.name}</p>
			<p>$${product.price.toFixed(2)}</p>
			<p>Quantity: ${cart[productId].quantity}</p>
			<button class="remove-from-cart-btn" data-id="${productId}">Remove</button>
		`;
		cartItems.appendChild(cartItemDiv);
		total += product.price * cart[productId].quantity;
	}
	// Update cart total
	cartTotal.textContent = total.toFixed(2);
	// Add event listener to "Remove" buttons
	const removeFromCartButtons = document.querySelectorAll('.remove-from-cart-btn');
	removeFromCartButtons.forEach(button => {
		button.addEventListener('click', event => {
			const productId = parseInt(event.target.dataset.id);
			removeFromCart(productId);
		});
	});
}
// Get product object by ID
function getProductById(productId) {
	const products = document.querySelectorAll('.product');
	for (let i = 0; i < products.length; i++) {
		if (parseInt(products[i].querySelector('.add-to-cart-btn').dataset.id) === productId) {
			return {
				id: productId,
				name: products[i].querySelector('h3').textContent,
				description: products[i].querySelector('p:nth-of-type(1)').textContent,
				price: parseFloat(products[i].querySelector('p:nth-of-type(2)').textContent.substr(1)),
				image: products[i].querySelector('img').getAttribute('src')
			};
		}
	}
}
```

