double p0 = 100000; // Standard atmospheric pressure in Pascals
double t0 = 288.15; // Standard temperature in Kelvin
double g = 9.81; // Acceleration due to gravity in m/s^2
double r = 287; // Gas constant for dry air in J/kg K
double cp = 1004; // Specific heat capacity for dry air in J/kg K
double PressureAtAltitude(double h)
{
    return p0 * Math.Pow(1 - (g * h) / (r * t0), g / (cp * r));
}
double TemperatureAtAltitude(double h)
{
    return t0 - (g * h) / cp;
}
