object NumberPuzzle {
  def main(args: Array[String]): Unit = {
    val numbers = List(2, 3, 5, 6, 10, 25)
    val target = 120
    val solutions = for {
      a <- numbers
      b <- numbers.filter(_ != a)
      c <- numbers.filter(n => n != a && n != b)
      d <- numbers.filter(n => n != a && n != b && n != c)
      e <- numbers.filter(n => n != a && n != b && n != c && n != d)
      f <- numbers.filter(n => n != a && n != b && n != c && n != d && n != e)
