To use the Stanford CoreNLP library in C++, you can use the StanfordNLP C++ library, which provides a C++ interface to the CoreNLP Java API.
Here is an example code snippet that uses the StanfordNLP library to identify the POS and definition of each word in the sentence "The government has announced new lockdown measures" and stores the results in an Excel table with columns for word, POS, and definition:
```
#include <iostream>
#include <string>
#include <vector>
#include <stanfordnlp/stanza.h>
#include <xlnt/xlnt.hpp>
int main() {
    // Initialize the StanfordNLP library
    stanfordnlp::init();
    // Create a pipeline with the POS and lemma annotators
    stanfordnlp::Pipeline* pipeline = new stanfordnlp::Pipeline("en", "", stanfordnlp::Pipeline::FLAG_POS | stanfordnlp::Pipeline::FLAG_LEMMA);
    // Define the input sentence
    std::string input_sentence = "The government has announced new lockdown measures";
    // Process the input sentence with the pipeline
    stanfordnlp::Document* document = new stanfordnlp::Document(input_sentence, pipeline);
    document->process();
    // Create an Excel workbook and worksheet
    xlnt::workbook workbook;
    xlnt::worksheet worksheet = workbook.active_sheet();
    worksheet.title("POS and Definition");
    // Add column headers to the worksheet
    worksheet.cell("A1").value("Word");
    worksheet.cell("B1").value("POS");
    worksheet.cell("C1").value("Definition");
    // Loop through each sentence in the document
    for (const auto& sentence : document->sentences()) {
        // Loop through each token in the sentence
        for (const auto& token : sentence->tokens()) {
            // Get the word, POS, and definition of the token
            std::string word = token->word();
            std::string pos = token->pos();
            std::string definition = token->lemma();
            // Add the word, POS, and definition to the worksheet
            int row = worksheet.rows().size() + 1;
            worksheet.cell("A" + std::to_string(row)).value(word);
            worksheet.cell("B" + std::to_string(row)).value(pos);
            worksheet.cell("C" + std::to_string(row)).value(definition);
        }
    }
    // Count the total number of nouns, verbs, and adjectives in the sentence
    int noun_count = 0;
    int verb_count = 0;
    int adj_count = 0;
    for (const auto& sentence : document->sentences()) {
        for (const auto& token : sentence->tokens()) {
            std::string pos = token->pos();
            if (pos == "NN" || pos == "NNS" || pos == "NNP" || pos == "NNPS") {
                noun_count++;
            } else if (pos == "VB" || pos == "VBD" || pos == "VBG" || pos == "VBN" || pos == "VBP" || pos == "VBZ") {
                verb_count++;
            } else if (pos == "JJ" || pos == "JJR" || pos == "JJS") {
                adj_count++;
            }
        }
    }
    // Print the total number of nouns, verbs, and adjectives in the sentence
    std::cout << "Total nouns: " << noun_count << std::endl;
    std::cout << "Total verbs: " << verb_count << std::endl;
    std::cout << "Total adjectives: " << adj_count << std::endl;
    // Save the workbook to a file
    workbook.save("POS and Definition.xlsx");
    // Clean up the pipeline and document objects
    delete document;
    delete pipeline;
    // Shutdown the StanfordNLP library
    stanfordnlp::shutdown();
    return 0;
}
```
Note that you will need to install the StanfordNLP and xlnt libraries and link them to your C++ project. Also, the above code assumes that you are using a C++11 or later compiler.

