// Pick one vegetarian and one gluten-free dish, if available
let vegetarianDish = satisfactoryDishes.find(dish => dish.ingredients.some(ingredient => VEGETARIAN_INGREDIENTS.includes(ingredient)));
let glutenFreeDish = satisfactoryDishes.find(dish => dish.ingredients.every(ingredient => GLUTEN_FREE_INGREDIENTS.includes(ingredient)));
// Sort the remaining dishes by descending order of profit (price minus cost)
const remainingDishes = satisfactoryDishes.filter(dish => dish !== vegetarianDish && dish !== glutenFreeDish);
remainingDishes.sort((a, b) => (b.price - INGREDIENT_COSTS[b.ingredients[0]]) - (a.price - INGREDIENT_COSTS[a.ingredients[0]]));
// Pick the dishes that maximize the total profit while staying within the cost limit
let totalCost = 0;
let totalProfit = 0;
const menu = [];
if (vegetarianDish) {
  menu.push(vegetarianDish);
  totalCost += vegetarianDish.ingredients.reduce((total, ingredient) => total + INGREDIENT_COSTS[ingredient], 0);
  totalProfit += vegetarianDish.price - INGREDIENT_COSTS[vegetarianDish.ingredients[0]];
}
if (glutenFreeDish) {
