  totalCost += glutenFreeDish.ingredients.reduce((total, ingredient) => total + INGREDIENT_COSTS[ingredient], 0);
  totalProfit += glutenFreeDish.price - INGREDIENT_COSTS[glutenFreeDish.ingredients[0]];
}
for (const dish of remainingDishes) {
  if (totalCost + dish.ingredients.reduce((total, ingredient) => total + INGREDIENT_COSTS[ingredient], 0) <= MAX_COST) {
    menu.push(dish);
    totalCost += dish.ingredients.reduce((total, ingredient) => total + INGREDIENT_COSTS[ingredient], 0);
