To create a function that utilizes a binary matrix representation of a maze to compute the optimal path, you can use the A* algorithm. Here's an example code snippet that you can modify to suit your needs:
```
function [path, cost] = findPath(maze, start, goal)
% maze: binary matrix representation of the maze
% start: starting position in the maze
% goal: goal position in the maze
% Define the heuristic function for A*
heuristic = @(pos) norm(pos - goal);
% Initialize the start node
startNode = struct('pos', start, 'g', 0, 'h', heuristic(start), 'f', 0, 'parent', []);
% Initialize the open and closed sets
openSet = startNode;
closedSet = [];
% Loop until the open set is empty or the goal is reached
while ~isempty(openSet)
    % Find the node with the lowest f value in the open set
    [~, idx] = min([openSet.f]);
    currentNode = openSet(idx);

    % If the goal is reached, construct the path and return
    if isequal(currentNode.pos, goal)
        path = constructPath(currentNode);
        cost = currentNode.g;
        return;
    end

    % Move the current node from the open set to the closed set
    openSet(idx) = [];
    closedSet(end+1) = currentNode;

    % Generate the successors of the current node
    successors = generateSuccessors(currentNode, maze);

    % Loop through the successors
    for i = 1:length(successors)
        successor = successors(i);

        % If the successor is in the closed set, skip it
        if any(isequal(successor.pos, [closedSet.pos]))
            continue;
        end

        % Calculate the tentative g value for the successor
        tentativeG = currentNode.g + 1;

        % If the successor is not in the open set, add it
        idx = find(isequal(successor.pos, [openSet.pos]), 1);
        if isempty(idx)
            successor.g = tentativeG;
            successor.h = heuristic(successor.pos);
            successor.f = successor.g + successor.h;
            successor.parent = currentNode;
            openSet(end+1) = successor;
        else
            % If the tentative g value is lower than the current g value,
            % update the node in the open set
            if tentativeG < openSet(idx).g
                openSet(idx).g = tentativeG;
                openSet(idx).f = openSet(idx).g + openSet(idx).h;
                openSet(idx).parent = currentNode;
            end
        end
    end
end
% If the goal is not reachable, return an empty path and NaN cost
path = [];
cost = NaN;
end
function path = constructPath(node)
% Construct the path from the goal node to the start node
path = node.pos;
while ~isempty(node.parent)
    node = node.parent;
    path = [node.pos; path];
end
end
function successors = generateSuccessors(node, maze)
% Generate the successors of a node in the maze
successors = [];
for dx = [-1, 0, 1]
    for dy = [-1, 0, 1]
        % Skip diagonal movements
        if abs(dx) == abs(dy)
            continue;
        end

        % Calculate the position of the successor
        pos = node.pos + [dx, dy];

        % Skip positions outside the maze
        if any(pos < 1) || any(pos > size(maze))
            continue;
        end

        % Skip positions with walls
        if maze(pos(1), pos(2)) == 1
            continue;
        end

        % Add the successor to the list
        successors(end+1) = struct('pos', pos, 'g', 0, 'h', 0, 'f', 0, 'parent', []);
    end
end
end
```
To ensure that the function implements multiple-step reasoning and complex decision-making processes to find the optimal path, you can modify the heuristic function to take into account the distance and obstacles between the current node and the goal node. For example, you can use a weighted combination of the Euclidean distance and the number of walls between the two nodes as the heuristic. This will encourage the algorithm to explore paths that are closer to the goal and have fewer obstacles.

