import javax.xml.parsers.*;
import javax.xml.xpath.*;
import org.w3c.dom.*;
import java.io.*;
public class ExpressionEvaluator {
    public static void main(String[] args) throws Exception {
        String expression = "<expression><operand><operand>6</operand><operator>*</operator><operand>3</operand></operand><operator>+</operator><operand><operand>2</operand><operator>^</operator><operand>3</operand></operand><operator>-</operator><operand>10</operand></expression>";
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.parse(new InputSource(new StringReader(expression)));
        XPathFactory xpathFactory = XPathFactory.newInstance();
        XPath xpath = xpathFactory.newXPath();
        double result = evaluateExpression(xpath, doc.getDocumentElement());
        System.out.println(result);
    }
    private static double evaluateExpression(XPath xpath, Node node) throws XPathExpressionException {
        NodeList children = node.getChildNodes();
        double left = evaluateOperand(xpath, children.item(0));
        double right = evaluateOperand(xpath, children.item(2));
        String operator = children.item(1).getTextContent();
        switch (operator) {
            case "+":
                return left + right;
            case "-":
                return left - right;
            case "*":
                return left * right;
            case "/":
                return left / right;
            case "^":
                return Math.pow(left, right);
            default:
                throw new IllegalArgumentException("Unknown operator: " + operator);
        }
    }
    private static double evaluateOperand(XPath xpath, Node node) throws XPathExpressionException {
        NodeList children = node.getChildNodes();
        if (children.getLength() == 1) {
            return Double.parseDouble(children.item(0).getTextContent());
        } else {
            return evaluateExpression(xpath, node);
        }
    }
}
