How can I use Go to scrape the content of this HTML page and extract the headline, subheadings, and body text for further analysis?
[Go code]
package main
import (
    "fmt"
    "net/http"
    "io/ioutil"
    "golang.org/x/net/html"
)
func main() {
    url := "https://www.example.com/article"
    resp, err := http.Get(url)
    if err != nil {
        panic(err)
    }
    defer resp.Body.Close()
    content, err := ioutil.ReadAll(resp.Body)
    if err != nil {
        panic(err)
    }
    doc, err := html.Parse(strings.NewReader(string(content)))
    if err != nil {
        panic(err)
    }
    var headline string
    var subheadings []string
    var body string
    var traverse func(n *html.Node)
    traverse = func(n *html.Node) {
        if n.Type == html.ElementNode && n.Data == "h1" {
            headline = n.FirstChild.Data
        } else if n.Type == html.ElementNode && n.Data == "h2" {
            subheadings = append(subheadings, n.FirstChild.Data)
        } else if n.Type == html.TextNode && n.Parent.Data == "p" {
            body += n.Data
        }
        for c := n.FirstChild; c != nil; c = c.NextSibling {
            traverse(c)
        }
    }
    traverse(doc)
    fmt.Println("Headline:", headline)
    fmt.Println("Subheadings:", subheadings)
    fmt.Println("Body:", body)
}

